export function getGetAsyncSearchIdKey(
  args: InferRequestType<(typeof client._async_search)[':id']['$get']>,
) {
  return ['_async_search', '/_async_search/:id', args] as const
}

export function useGetAsyncSearchId<TError = unknown>(
  args: InferRequestType<(typeof client._async_search)[':id']['$get']>,
  options?: {
    swr?: SWRConfiguration<
      Awaited<
        ReturnType<
          typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
        >
      >,
      TError
    > & { swrKey?: Key; enabled?: boolean }
    options?: ClientRequestOptions
  },
) {
  const { swr: swrOptions, options: clientOptions } = options ?? {}
  const { swrKey: customKey, enabled, ...restSwrOptions } = swrOptions ?? {}
  const swrKey =
    enabled !== false ? (customKey === undefined ? getGetAsyncSearchIdKey(args) : customKey) : null
  return {
    swrKey,
    ...useSWR<
      Awaited<
        ReturnType<
          typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
        >
      >,
      TError
    >(
      swrKey,
      async () => parseResponse(client._async_search[':id'].$get(args, clientOptions)),
      restSwrOptions,
    ),
  }
}

